"""Generates scripts/art/excavator_kin.gd from exc_kin.py so the game and the Blender model share one set of numbers.
    python tools/vehicle_models/export_kin_gd.py"""
import os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
import exc_kin as K
REPO = os.path.dirname(os.path.dirname(HERE))
rl = K.rest_link()
def v2(p): return "Vector2(%.5f, %.5f)" % (p[0], p[1])
lines = [
    "extends RefCounted",
    "class_name ExcavatorKin",
    "## GENERATED by tools/vehicle_models/export_kin_gd.py from exc_kin.py - do not edit by hand.",
    "## Planar (y forward, z up) excavator linkage constants. Godot frame: model forward is -Z, so a model-space (y, z) point is (0, z, -y).",
    "",
    "const ARM_S := %.5f" % K.ARM_S,
    "const P0 := " + v2(K.P0),
    "const BOOM_E := " + v2(K.BOOM_E),
    "const STICK_W := " + v2(K.STICK_W),
    "const REST := {\"swing\": %.4f, \"boom\": %.4f, \"stick\": %.4f, \"bucket\": %.4f}" % tuple(K.REST[k] for k in ("swing", "boom", "stick", "bucket")),
    "const LIMITS := {\"boom\": Vector2(%.4f, %.4f), \"stick\": Vector2(%.4f, %.4f), \"bucket\": Vector2(%.4f, %.4f)}" % (*K.LIMITS["boom"], *K.LIMITS["stick"], *K.LIMITS["bucket"]),
    "const BOOM_CYL_BASE := " + v2(K.BOOM_CYL["base"]),
    "const BOOM_CYL_ROD := " + v2(K.BOOM_CYL["rod"]),
    "const STICK_CYL_BASE := " + v2(K.STICK_CYL["base"]),
    "const STICK_CYL_ROD := " + v2(K.STICK_CYL["rod"]),
    "const BUCKET_CYL_BASE := " + v2(K.BUCKET_CYL["base"]),
    "const LINK_K := " + v2(K.LINK_K),
    "const LINK_L := " + v2(K.LINK_L),
    "const LINK_IDLER_LEN := %.5f" % rl["lk"],
    "const LINK_BUCKET_LEN := %.5f" % rl["ll"],
    "const TIP := " + v2(K.TIP),
    "const CYL_RANGES := {" + ", ".join("\"%s\": Vector2(%.4f, %.4f)" % (k, v[0], v[1]) for k, v in K.cyl_ranges().items()) + "}",
    "",
    "static func rot(p: Vector2, a: float) -> Vector2:",
    "\tvar c := cos(a)",
    "\tvar s := sin(a)",
    "\treturn Vector2(p.x * c - p.y * s, p.x * s + p.y * c)",
    "",
    "## Intersection of two circles; `side` picks the branch (matches exc_kin.circle_hit). Returns Vector2.INF when out of reach.",
    "static func circle_hit(p0: Vector2, r0: float, p1: Vector2, r1: float, side: float) -> Vector2:",
    "\tvar d := p0.distance_to(p1)",
    "\tvar a := (r0 * r0 - r1 * r1 + d * d) / (2.0 * d)",
    "\tvar h2 := r0 * r0 - a * a",
    "\tif h2 < 0.0:",
    "\t\treturn Vector2.INF",
    "\tvar h := sqrt(h2)",
    "\tvar e := (p1 - p0) / d",
    "\tvar m := p0 + e * a",
    "\treturn Vector2(m.x - side * h * e.y, m.y + side * h * e.x)",
    "",
    "## Bucket joint J in the STICK frame for a bucket angle (stick-local, relative to the elbow).",
    "static func bucket_j(bucket: float) -> Vector2:",
    "\tvar l := STICK_W + rot(LINK_L, bucket)",
    "\treturn circle_hit(LINK_K, LINK_IDLER_LEN, l, LINK_BUCKET_LEN, -1.0)",
    "",
    "## Forward kinematics (model plane, y forward / z up): elbow, bucket pin and lip for absolute joint angles.",
    "static func fk(b: float, s: float, k: float) -> Dictionary:",
    "\tvar e := P0 + rot(BOOM_E, b)",
    "\tvar w := e + rot(STICK_W, b + s)",
    "\treturn {\"E\": e, \"W\": w, \"tip\": w + rot(TIP, b + s + k)}",
    "",
    "## Closed-form planar IK: lip target (y, z) + absolute bucket attitude -> Vector3(boom, stick, bucket_rel), Vector3.INF when out of reach.",
    "static func ik(target: Vector2, attitude: float) -> Vector3:",
    "\tvar w := target - rot(TIP, attitude)",
    "\tvar a := circle_hit(P0, BOOM_E.length(), w, STICK_W.length(), 1.0)",
    "\tvar b2 := circle_hit(P0, BOOM_E.length(), w, STICK_W.length(), -1.0)",
    "\tif a == Vector2.INF:",
    "\t\treturn Vector3.INF",
    "\tvar e := a if a.y >= b2.y else b2          # elbow up",
    "\tvar boom := atan2(e.y - P0.y, e.x - P0.x) - atan2(BOOM_E.y, BOOM_E.x)",
    "\tvar stick_abs := atan2(w.y - e.y, w.x - e.x) - atan2(STICK_W.y, STICK_W.x)",
    "\treturn Vector3(boom, stick_abs - boom, attitude - stick_abs)",
]
out = os.path.join(REPO, "scripts", "art", "excavator_kin.gd")
open(out, "w", newline="\n").write("\n".join(lines) + "\n")
print("wrote", out)
